const locales: Record<Locale, TranslationDict> = { en, it, de };

/** Translate a key using the current locale, falls back to English then key */
export function t(key: string, locale: Locale = 'en'): string {
  return locales[locale]?.[key] ?? locales['en'][key] ?? key;
}

